function controls(s){
function up(F,g){let p=new Map(),reads=0;for(let l of g){let v=Math.abs(l),b=Number(l>0);if(p.has(v)&&p.get(v)!==b)return {conflict:true,p,reads};p.set(v,b)}for(;;){let change=false;for(let c of F){let free=[],ok=false;for(let l of c){reads++;let v=Math.abs(l);if(!p.has(v))free.push(l);else if(p.get(v)===Number(l>0)){ok=true;break}}if(ok)continue;if(!free.length)return {conflict:true,p,reads};if(free.length===1){p.set(Math.abs(free[0]),Number(free[0]>0));change=true}}if(!change)return {conflict:false,p,reads}}}
function hall(F,g){let u=up(F,g);if(u.conflict)return {status:"UP_CONFLICT",reads:u.reads};let rows=[];for(let [i,c] of F.entries()){if(c.some(l=>u.p.has(Math.abs(l))&&u.p.get(Math.abs(l))===Number(l>0)))continue;rows.push({i,c:c.filter(l=>!u.p.has(Math.abs(l)))})}let used=new Set(),D=[];for(let r of rows.filter(r=>r.c.length>=2&&r.c.every(l=>l>0)).sort((a,b)=>a.c.length-b.c.length||a.i-b.i)){if(r.c.some(v=>used.has(v)))continue;D.push(r);r.c.forEach(v=>used.add(v))}let neg=new Map(rows.filter(r=>r.c.length===2&&r.c.every(l=>l<0)).map(r=>[r.c.map(l=>-l).sort((a,b)=>a-b).join(","),r.i])),bins=[],checks=0;for(let v of [...used].sort((a,b)=>a-b)){let b=bins.find(b=>b.every(w=>{checks++;return neg.has([w,v].sort((a,b)=>a-b).join(","))}));if(b)b.push(v);else bins.push([v])}let N=D.map(r=>bins.map((b,j)=>b.some(v=>r.c.includes(v))?j:-1).filter(j=>j>=0)),match=new Map(),vis=0;function aug(i,S){for(let j of N[i]){vis++;if(S.has(j))continue;S.add(j);if(!match.has(j)||aug(match.get(j),S)){match.set(j,i);return true}}return false}let bad=null;for(let i=0;i<D.length;i++){let S=new Set();if(!aug(i,S)){let ds=new Set([i]);for(let j of S)if(match.has(j))ds.add(match.get(j));let nb=new Set([...ds].flatMap(i=>N[i]));if(nb.size>=ds.size)throw Error("Hall");bad={demandIds:[...ds].map(i=>D[i].i),binIds:[...nb],deficit:ds.size-nb.size};break}}return {status:bad?"HALL_UNSAT":"UNKNOWN",reads:u.reads,demands:D.length,bins:bins.length,matching:match.size,cliqueChecks:checks,augmentVisits:vis,bad,binMap:bins,demandRows:D.map(r=>r.i)}}
let results=JSON.parse(s.results);return ["joint","random"].map((key,i)=>{let F=JSON.parse(s[key]).chart,V=[...new Set(F.flat().map(Math.abs))].sort((a,b)=>a-b),guards=results[i].guards.map(x=>x.g),h=[[],...guards].map(g=>({g,...hall(F,g)}));let seed=20261128,rand=n=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return (seed>>>8)%n},read=0,tries=0,hits=[],seen=new Set(),verify=0,draws=0;while(tries<64&&read<100000&&draws++<512){let a=V[rand(V.length)],b=V[rand(V.length)];if(a===b)continue;let g=[rand(2)?a:-a,rand(2)?b:-b].sort((x,y)=>x-y),k=g.join(",");if(seen.has(k))continue;seen.add(k);tries++;let x=up(F,g);read+=x.reads;if(x.conflict){let y=up(F,g.slice().reverse());verify+=y.reads;if(!y.conflict)throw Error("RUP");hits.push(g.map(l=>-l))}}return {id:results[i].id,hall:h,stochastic:{seed:20261128,draws,tries,reads:read,verify,hits:hits.length,clauses:hits}}})
}
if(typeof require==='function'){let fs=require('fs'),keys=['joint','random','results'];let s=Object.fromEntries(keys.map((k,i)=>[k,fs.readFileSync(process.argv[i+2],'utf8')]));console.log(JSON.stringify(controls(s),null,2));}
